// Código de Processo Penal — somente os artigos do edital: 251 a 258; 261 a 267; 274; 351 a 372; 394 a 497; 531 a 538; 541 a 548; 574 a 667.
// Texto conferido com a legislação compilada do edital. "caiu 20XX QN" = questão das provas reais 2024 (reaplicada) e 2025.
window.CARDS = (window.CARDS || []).concat([
  { id: "cpp-1", lei: "Código de Processo Penal", ref: "CPP art. 251",
    frente: "Qual é a incumbência do juiz no processo (art. 251)?",
    verso: "Prover à REGULARIDADE do processo e manter a ORDEM no curso dos atos, podendo, para tal fim, REQUISITAR A FORÇA PÚBLICA." },
  { id: "cpp-2", lei: "Código de Processo Penal", ref: "CPP art. 252 · caiu 2025 Q21 e 2024 Q31",
    frente: "Impedimento do juiz (art. 252): quais são as hipóteses?",
    verso: "O juiz NÃO pode exercer jurisdição no processo em que: I tiver funcionado seu CÔNJUGE ou PARENTE (consanguíneo ou afim, em linha reta ou colateral até o 3º GRAU) como defensor, advogado, órgão do MP, autoridade policial, auxiliar da justiça ou perito; II ELE PRÓPRIO tiver desempenhado qualquer dessas funções ou servido como testemunha; III tiver funcionado como JUIZ DE OUTRA INSTÂNCIA, pronunciando-se, de fato ou de direito, sobre a questão; IV ele próprio, seu cônjuge ou parente até o 3º grau for PARTE ou DIRETAMENTE INTERESSADO no feito. (Primo é parente de 4º grau.)" },
  { id: "cpp-3", lei: "Código de Processo Penal", ref: "CPP art. 253",
    frente: "Impedimento nos juízos coletivos (art. 253).",
    verso: "Não poderão servir no mesmo processo os juízes que forem entre si PARENTES, consanguíneos ou afins, em linha reta ou colateral até o TERCEIRO GRAU, inclusive." },
  { id: "cpp-4", lei: "Código de Processo Penal", ref: "CPP art. 254 · caiu 2025 Q21",
    frente: "Suspeição do juiz (art. 254): quais são as hipóteses?",
    verso: "O juiz dar-se-á por suspeito e, se não o fizer, poderá ser recusado por qualquer das partes: I amigo íntimo ou inimigo capital de qualquer deles; II ele, seu cônjuge, ascendente ou descendente estiver respondendo a processo por fato análogo, sobre cujo caráter criminoso haja controvérsia; III ele, seu cônjuge ou parente até o 3º grau sustentar demanda ou responder a processo que tenha de ser julgado por qualquer das partes; IV tiver ACONSELHADO qualquer das partes; V for CREDOR ou DEVEDOR, TUTOR ou CURADOR de qualquer das partes; VI for sócio, acionista ou administrador de sociedade interessada no processo." },
  { id: "cpp-5", lei: "Código de Processo Penal", ref: "CPP arts. 252 e 254 · caiu 2025 Q21",
    frente: "IMPEDIMENTO ou SUSPEIÇÃO? Cônjuge diretamente interessado no feito; ter aconselhado uma das partes; credor ou devedor da parte; ter atuado como juiz de outra instância na questão.",
    verso: "Cônjuge diretamente interessado: IMPEDIMENTO (252, IV). Ter aconselhado a parte: SUSPEIÇÃO (254, IV). Credor ou devedor, tutor ou curador da parte: SUSPEIÇÃO (254, V). Juiz de outra instância que se pronunciou sobre a questão: IMPEDIMENTO (252, III). Impedimento: causas em rol específico; suspeição: razões subjetivas de parcialidade, inclusive amizade e inimizade." },
  { id: "cpp-6", lei: "Código de Processo Penal", ref: "CPP art. 255",
    frente: "Impedimento ou suspeição por parentesco por afinidade: cessa com a dissolução do casamento?",
    verso: "Cessa pela dissolução do casamento que lhe tiver dado causa, SALVO sobrevindo DESCENDENTES. Mesmo dissolvido o casamento sem descendentes, não funcionará como juiz o SOGRO, o PADRASTO, o CUNHADO, o GENRO ou ENTEADO de quem for parte no processo." },
  { id: "cpp-7", lei: "Código de Processo Penal", ref: "CPP art. 256",
    frente: "Quando a suspeição NÃO pode ser declarada nem reconhecida (art. 256)?",
    verso: "Quando a PARTE INJURIAR o juiz ou, de propósito, der motivo para criá-la." },
  { id: "cpp-8", lei: "Código de Processo Penal", ref: "CPP art. 257",
    frente: "Atribuições do Ministério Público no processo penal (art. 257).",
    verso: "I promover, PRIVATIVAMENTE, a ação penal pública, na forma do Código; II fiscalizar a execução da lei." },
  { id: "cpp-9", lei: "Código de Processo Penal", ref: "CPP art. 258",
    frente: "Impedimento e suspeição dos órgãos do Ministério Público (art. 258).",
    verso: "Os órgãos do MP não funcionarão nos processos em que o juiz ou qualquer das partes for seu cônjuge ou parente, consanguíneo ou afim, em linha reta ou colateral, até o 3º grau, inclusive. A eles se estendem, no que for aplicável, as regras de suspeição e impedimento dos juízes." },
  { id: "cpp-10", lei: "Código de Processo Penal", ref: "CPP art. 261",
    frente: "Defesa técnica no processo penal (art. 261): qual a regra?",
    verso: "NENHUM acusado, ainda que AUSENTE ou FORAGIDO, será processado ou julgado SEM DEFENSOR. A defesa técnica, quando feita por defensor público ou dativo, será sempre exercida por MANIFESTAÇÃO FUNDAMENTADA (parágrafo único)." },
  { id: "cpp-11", lei: "Código de Processo Penal", ref: "CPP arts. 262 a 264",
    frente: "Art. 262 (curador do menor), art. 263 (defensor nomeado) e art. 264 (multa ao advogado).",
    verso: "Art. 262 (acusado menor terá curador): dispositivo tacitamente revogado. Art. 263: se o acusado não tiver defensor, o juiz nomeia, ressalvado o direito de, a todo tempo, nomear outro de sua confiança ou DEFENDER-SE A SI MESMO, caso tenha HABILITAÇÃO; o acusado que não for pobre pagará os honorários do dativo, arbitrados pelo juiz. Art. 264: salvo motivo relevante, os advogados e solicitadores são obrigados a prestar patrocínio quando nomeados pelo juiz, sob pena de multa." },
  { id: "cpp-12", lei: "Código de Processo Penal", ref: "CPP art. 265, caput e §1º",
    frente: "Abandono do processo pelo defensor e adiamento de audiência (art. 265, caput e §1º).",
    verso: "Caput: o defensor NÃO pode abandonar o processo sem justo motivo, PREVIAMENTE comunicado ao juiz, sob pena de responder por infração disciplinar perante o ÓRGÃO CORREICIONAL competente. §1º: a audiência poderá ser adiada se, por motivo justificado, o defensor não puder comparecer." },
  { id: "cpp-13", lei: "Código de Processo Penal", ref: "CPP art. 265, §§2º e 3º · caiu 2024 Q32",
    frente: "Defensor que abandona o processo e acusado que não é localizado: o que o juiz faz (art. 265, §3º)?",
    verso: "Primeiro o acusado é INTIMADO para constituir novo defensor, se quiser; se NÃO FOR LOCALIZADO, o juiz nomeia DEFENSOR PÚBLICO ou ADVOGADO DATIVO para a defesa. §2º: incumbe ao defensor provar o impedimento até a abertura da audiência; se não provar, o juiz não adia o ato e nomeia defensor substituto, ainda que provisoriamente ou só para o ato. O processo NÃO é sobrestado." },
  { id: "cpp-14", lei: "Código de Processo Penal", ref: "CPP art. 266 · caiu 2025 Q22",
    frente: "Quando a constituição de defensor independe de instrumento de mandato?",
    verso: "Se o acusado o INDICAR por ocasião do INTERROGATÓRIO (nomeação 'apud acta')." },
  { id: "cpp-15", lei: "Código de Processo Penal", ref: "CPP art. 267",
    frente: "Defensor parente do juiz (art. 267).",
    verso: "Nos termos do art. 252, NÃO funcionarão como defensores os PARENTES DO JUIZ." },
  { id: "cpp-16", lei: "Código de Processo Penal", ref: "CPP art. 274 · caiu 2024 Q33",
    frente: "Suspeição e serventuários e funcionários da justiça (art. 274).",
    verso: "As prescrições sobre SUSPEIÇÃO dos juízes ESTENDEM-SE aos serventuários e funcionários da justiça, no que lhes for aplicável. Ex. da prova: o diretor do cartório, amigo íntimo do réu, não pode atuar no feito." },
  { id: "cpp-17", lei: "Código de Processo Penal", ref: "CPP art. 351",
    frente: "Citação por mandado (art. 351): quando se usa?",
    verso: "A citação inicial far-se-á POR MANDADO quando o réu estiver no território sujeito à jurisdição do juiz que a houver ordenado." },
  { id: "cpp-18", lei: "Código de Processo Penal", ref: "CPP art. 352",
    frente: "Requisitos do mandado de citação (art. 352).",
    verso: "Indicará: I o nome do juiz; II o nome do querelante nas ações iniciadas por queixa; III o nome do réu, ou, se desconhecido, seus sinais característicos; IV a residência do réu, se conhecida; V o fim para que é feita a citação; VI o juízo, o lugar, o dia e a hora em que o réu deverá comparecer; VII a subscrição do escrivão e a rubrica do juiz." },
  { id: "cpp-19", lei: "Código de Processo Penal", ref: "CPP arts. 353 a 356",
    frente: "Citação por precatória (arts. 353 a 356).",
    verso: "Réu fora do território do juiz: citado mediante PRECATÓRIA (353). Ela indica: juiz deprecado e deprecante, sede da jurisdição de um e de outro, fim da citação com todas as especificações, juízo do lugar, dia e hora do comparecimento (354). É devolvida independentemente de traslado, depois do 'cumpra-se' e da citação por mandado do juiz deprecado (355). Precatória itinerante: o réu em jurisdição de outro juiz, para onde o deprecado remete os autos (355, §1º). Se o oficial certificar que o réu se oculta, a precatória é devolvida para a hora certa (355, §2º). Havendo urgência, pode ser expedida por via telegráfica (356)." },
  { id: "cpp-20", lei: "Código de Processo Penal", ref: "CPP art. 357",
    frente: "Requisitos da citação por mandado (art. 357).",
    verso: "I LEITURA do mandado ao citando pelo oficial e entrega da CONTRAFÉ, com menção de dia e hora; II DECLARAÇÃO do oficial, na certidão, da entrega da contrafé e de sua aceitação ou recusa." },
  { id: "cpp-21", lei: "Código de Processo Penal", ref: "CPP arts. 358 a 360 · caiu 2025 Q23",
    frente: "Citação do militar, do funcionário público e do réu preso: como se faz?",
    verso: "MILITAR: por intermédio do CHEFE do respectivo serviço (358). FUNCIONÁRIO PÚBLICO: o dia designado para comparecer em juízo como acusado será notificado ASSIM A ELE COMO ao CHEFE de sua repartição (359). RÉU PRESO: será PESSOALMENTE citado (360). (A prova listou como erradas: 'só ao chefe da repartição' e 'basta requisitar o preso ao diretor do presídio'.)" },
  { id: "cpp-22", lei: "Código de Processo Penal", ref: "CPP art. 361 · caiu 2025 Q23",
    frente: "Citação por edital: quando se faz e qual o prazo (art. 361)?",
    verso: "Se o réu NÃO FOR ENCONTRADO, será citado por EDITAL, com o prazo de 15 DIAS (citação ficta). Pegadinha: '120 dias' e 'carta-convite' (não existe)." },
  { id: "cpp-23", lei: "Código de Processo Penal", ref: "CPP art. 362 · caiu 2024 Q34",
    frente: "Citação por hora certa no processo penal (art. 362).",
    verso: "Se o réu se OCULTA para não ser citado, o oficial certifica e procede à citação com HORA CERTA, na forma do CPC. Completada a citação, se o acusado NÃO COMPARECER, ser-lhe-á nomeado DEFENSOR DATIVO (parágrafo único). Não há suspensão do processo." },
  { id: "cpp-24", lei: "Código de Processo Penal", ref: "CPP art. 363",
    frente: "Formação do processo e citação por edital (art. 363).",
    verso: "O processo terá completada a sua formação quando realizada a CITAÇÃO do acusado. Não sendo encontrado, será procedida a citação por EDITAL (§1º). Comparecendo o acusado citado por edital, em qualquer tempo, o processo observará o disposto nos arts. 394 e seguintes (§4º)." },
  { id: "cpp-25", lei: "Código de Processo Penal", ref: "CPP arts. 364 e 365", conferir: true,
    frente: "Prazo e conteúdo do edital de citação (arts. 364 e 365).",
    verso: "Art. 365: o edital indica o nome do juiz, o nome do réu (ou sinais característicos, residência e profissão), o fim da citação, o juízo, o dia, a hora e o lugar de comparecimento e o PRAZO, contado do dia da publicação na imprensa, se houver, ou da afixação. Afixa-se à PORTA do edifício do juízo e publica-se pela imprensa, onde houver. Art. 364: o prazo é fixado entre 15 e 90 dias, conforme as circunstâncias, nas hipóteses do artigo (a regra do art. 361 é de 15 dias)." },
  { id: "cpp-26", lei: "Código de Processo Penal", ref: "CPP art. 366",
    frente: "Citado por edital que não comparece nem constitui advogado: o que acontece (art. 366)?",
    verso: "Ficam SUSPENSOS o PROCESSO e o CURSO DO PRAZO PRESCRICIONAL, podendo o juiz determinar a produção ANTECIPADA das provas consideradas urgentes e, se for o caso, decretar prisão preventiva (art. 312). (Diferente da hora certa, que não suspende.)" },
  { id: "cpp-27", lei: "Código de Processo Penal", ref: "CPP art. 367",
    frente: "Revelia no processo penal (art. 367).",
    verso: "O processo seguirá SEM A PRESENÇA do acusado que, citado ou intimado PESSOALMENTE para qualquer ato, deixar de comparecer sem motivo justificado, ou, no caso de mudança de residência, não comunicar o novo endereço ao juízo. Mesmo revel, nenhum acusado fica sem defensor." },
  { id: "cpp-28", lei: "Código de Processo Penal", ref: "CPP arts. 368 e 369",
    frente: "Réu no estrangeiro e legações estrangeiras (arts. 368 e 369).",
    verso: "Réu no estrangeiro, em lugar sabido: citado mediante CARTA ROGATÓRIA, suspendendo-se o curso do prazo de prescrição até o seu cumprimento (368). Citações em LEGAÇÕES ESTRANGEIRAS: também por carta rogatória (369)." },
  { id: "cpp-29", lei: "Código de Processo Penal", ref: "CPP art. 370",
    frente: "Intimações (art. 370): como é intimado o defensor constituído e como o MP e o defensor nomeado?",
    verso: "Aplicam-se, no que couber, as regras da citação. Defensor constituído, advogado do querelante e assistente: por PUBLICAÇÃO no órgão incumbido da publicidade dos atos judiciais, incluindo, sob pena de NULIDADE, o NOME DO ACUSADO (§1º). Sem órgão de publicação: pelo escrivão, por mandado, via postal ou outro meio idôneo (§2º). Intimação pessoal feita pelo escrivão dispensa a publicação (§3º). MP e defensor NOMEADO: intimação PESSOAL (§4º)." },
  { id: "cpp-30", lei: "Código de Processo Penal", ref: "CPP arts. 371 e 372",
    frente: "Intimação por despacho e adiamento da instrução (arts. 371 e 372).",
    verso: "Art. 371: é admissível a intimação por DESPACHO na petição em que for requerida, observado o art. 357. Art. 372: adiada, por qualquer motivo, a instrução criminal, o juiz marcará desde logo, na presença das partes e testemunhas, dia e hora para seu prosseguimento, do que se lavrará termo nos autos." },
  { id: "cpp-31", lei: "Código de Processo Penal", ref: "CPP art. 394, §1º · caiu 2025 Q24 e 2024 Q35",
    frente: "Procedimento comum: ordinário, sumário e sumaríssimo (art. 394, §1º).",
    verso: "ORDINÁRIO: crime cuja sanção máxima cominada for IGUAL OU SUPERIOR a 4 ANOS de pena privativa de liberdade. SUMÁRIO: sanção máxima INFERIOR a 4 anos. SUMARÍSSIMO: infrações de menor potencial ofensivo, na forma da lei. O procedimento é COMUM ou ESPECIAL (o 'especial' não é espécie do comum)." },
  { id: "cpp-32", lei: "Código de Processo Penal", ref: "CPP art. 394, §§2º a 5º",
    frente: "Art. 394, §2º a §5º: regra geral, júri e aplicação subsidiária.",
    verso: "§2º: aplica-se a todos os processos o procedimento COMUM, salvo disposições em contrário do Código ou de lei especial. §3º: nos processos de competência do Tribunal do Júri, observam-se os arts. 406 a 497. §4º: os arts. 395 a 398 aplicam-se a todos os procedimentos penais de primeiro grau. §5º: aplicam-se subsidiariamente aos procedimentos especial, sumário e sumaríssimo as disposições do ordinário." },
  { id: "cpp-33", lei: "Código de Processo Penal", ref: "CPP art. 394-A · caiu 2025 Q24",
    frente: "Prioridade de tramitação em crime hediondo e violência contra a mulher (art. 394-A).",
    verso: "Os processos que apurem crime HEDIONDO ou violência contra a MULHER têm prioridade de tramitação em TODAS as instâncias (sem exigência de requerimento). §1º: os processos de violência contra a mulher independem do pagamento de custas, taxas ou despesas, salvo má-fé. §2º: a isenção aplica-se apenas à VÍTIMA e, em caso de morte, ao cônjuge, ascendente, descendente ou irmão." },
  { id: "cpp-34", lei: "Código de Processo Penal", ref: "CPP art. 395",
    frente: "Quando a denúncia ou queixa será REJEITADA (art. 395)?",
    verso: "I for manifestamente INEPTA; II faltar PRESSUPOSTO PROCESSUAL ou CONDIÇÃO para o exercício da ação penal; III faltar JUSTA CAUSA para o exercício da ação penal." },
  { id: "cpp-35", lei: "Código de Processo Penal", ref: "CPP art. 396 · caiu 2025 Q24",
    frente: "Resposta à acusação nos procedimentos ordinário e sumário (art. 396): prazo e citação por edital.",
    verso: "Oferecida a denúncia ou queixa, o juiz, se não a rejeitar liminarmente, a recebe e ordena a CITAÇÃO do acusado para responder à acusação, POR ESCRITO, no prazo de 10 DIAS. Citação por EDITAL: o prazo começa a fluir a partir do COMPARECIMENTO PESSOAL do acusado ou do defensor constituído." },
  { id: "cpp-36", lei: "Código de Processo Penal", ref: "CPP art. 396-A",
    frente: "O que o acusado pode fazer na resposta à acusação (art. 396-A)?",
    verso: "Arguir preliminares e alegar tudo que interesse à sua defesa, oferecer documentos e justificações, especificar as provas pretendidas e ARROLAR TESTEMUNHAS, qualificando-as e requerendo sua intimação, quando necessário. A EXCEÇÃO é processada em apartado (arts. 95 a 112). Se a resposta não for apresentada no prazo ou o acusado, citado, não constituir defensor, o juiz NOMEIA defensor para oferecê-la, com vista por 10 DIAS." },
  { id: "cpp-37", lei: "Código de Processo Penal", ref: "CPP art. 397",
    frente: "Absolvição sumária (art. 397): quais são as hipóteses?",
    verso: "Após a resposta, o juiz deve absolver sumariamente o acusado quando verificar: I existência MANIFESTA de causa excludente da ILICITUDE; II existência manifesta de causa excludente da CULPABILIDADE, SALVO INIMPUTABILIDADE; III que o fato narrado EVIDENTEMENTE NÃO CONSTITUI CRIME; IV extinta a PUNIBILIDADE. (O art. 398 foi revogado.)" },
  { id: "cpp-38", lei: "Código de Processo Penal", ref: "CPP art. 399",
    frente: "Recebida a denúncia: audiência, acusado preso e identidade física do juiz (art. 399).",
    verso: "O juiz designa dia e hora para a AUDIÊNCIA, ordenando a intimação do acusado, de seu defensor, do MP e, se for o caso, do querelante e do assistente. O acusado PRESO será requisitado para o interrogatório, devendo o poder público providenciar sua apresentação (§1º). O juiz que PRESIDIU a instrução deverá proferir a SENTENÇA (§2º)." },
  { id: "cpp-39", lei: "Código de Processo Penal", ref: "CPP art. 400",
    frente: "Audiência de instrução e julgamento no procedimento ordinário (art. 400): prazo e ordem dos atos.",
    verso: "Será realizada no prazo máximo de 60 DIAS. Ordem: declarações do ofendido; testemunhas da ACUSAÇÃO e da DEFESA, nesta ordem (ressalvado o art. 222); esclarecimentos dos peritos; acareações; reconhecimento de pessoas e coisas; por último, o INTERROGATÓRIO do acusado. As provas são produzidas numa só audiência; o juiz pode indeferir as irrelevantes, impertinentes ou protelatórias (§1º). Esclarecimentos dos peritos dependem de prévio requerimento (§2º)." },
  { id: "cpp-40", lei: "Código de Processo Penal", ref: "CPP art. 400-A",
    frente: "Respeito à vítima na audiência (art. 400-A, Lei Mariana Ferrer).",
    verso: "Todas as partes e sujeitos processuais devem zelar pela integridade física e psicológica da vítima, sob pena de responsabilização civil, penal e administrativa, cabendo ao juiz garantir o cumprimento. VEDADAS: I manifestação sobre circunstâncias ou elementos ALHEIOS aos fatos; II linguagem, informações ou material que OFENDAM a dignidade da vítima ou de testemunhas." },
  { id: "cpp-41", lei: "Código de Processo Penal", ref: "CPP art. 401 · caiu 2024 Q35",
    frente: "Número de testemunhas no procedimento ordinário (art. 401).",
    verso: "Até 8 (OITO) testemunhas arroladas pela acusação e 8 pela defesa. Não se compreendem nesse número as que não prestem compromisso e as referidas. A parte pode desistir da inquirição de qualquer testemunha, ressalvado o art. 209. (No SUMÁRIO são 5 por parte, art. 532.)" },
  { id: "cpp-42", lei: "Código de Processo Penal", ref: "CPP arts. 402 e 403",
    frente: "Diligências e alegações finais no ordinário (arts. 402 e 403).",
    verso: "Art. 402: ao final da audiência, MP, querelante, assistente e, a seguir, o acusado podem requerer diligências cuja necessidade se origine de fatos apurados na instrução. Art. 403: sem diligências, alegações finais ORAIS por 20 MINUTOS, prorrogáveis por mais 10, para acusação e defesa, e o juiz profere sentença. Mais de um acusado: tempo individual (§1º). Assistente do MP: 10 minutos (§2º). Memoriais: 5 dias sucessivos e sentença em 10 dias, considerada a complexidade do caso (§3º)." },
  { id: "cpp-43", lei: "Código de Processo Penal", ref: "CPP arts. 404 e 405",
    frente: "Diligência imprescindível e registro da audiência (arts. 404 e 405).",
    verso: "Art. 404: ordenada diligência imprescindível, a audiência é concluída SEM as alegações finais; realizada a diligência, as partes apresentam alegações finais por MEMORIAL em 5 DIAS (sucessivos) e o juiz profere sentença em 10 DIAS. Art. 405: do ocorrido em audiência lavra-se TERMO em livro próprio, assinado pelo juiz e pelas partes, com breve resumo dos fatos relevantes; sempre que possível, depoimentos registrados por gravação magnética, estenotipia, digital ou audiovisual (§1º), sem necessidade de transcrição (§2º)." },
  { id: "cpp-44", lei: "Código de Processo Penal", ref: "CPP art. 406",
    frente: "Júri: resposta à acusação (art. 406): prazo, início da contagem e número de testemunhas.",
    verso: "O juiz, ao receber a denúncia ou queixa, ordena a citação para responder, por escrito, em 10 DIAS. O prazo conta do efetivo cumprimento do mandado ou do comparecimento em juízo do acusado ou de defensor constituído (citação inválida ou por edital). A ACUSAÇÃO arrola testemunhas na denúncia ou queixa, no máximo 8; na resposta, o acusado pode arguir preliminares, juntar documentos e arrolar testemunhas, no máximo 8." },
  { id: "cpp-45", lei: "Código de Processo Penal", ref: "CPP arts. 407 a 410",
    frente: "Júri: exceções, resposta não apresentada, manifestação do MP e diligências (arts. 407 a 410).",
    verso: "Art. 407: exceções processadas em apartado. Art. 408: não apresentada a resposta, o juiz NOMEIA defensor para oferecê-la em até 10 dias, com vista dos autos. Art. 409: apresentada a defesa, o juiz ouve o MP ou o querelante sobre preliminares e documentos em 5 DIAS. Art. 410: o juiz determina a inquirição das testemunhas e as diligências requeridas no prazo máximo de 10 DIAS." },
  { id: "cpp-46", lei: "Código de Processo Penal", ref: "CPP art. 411",
    frente: "Audiência de instrução no júri (art. 411): ordem, debates e prazos.",
    verso: "Declarações do ofendido, testemunhas da acusação e da defesa (nesta ordem), esclarecimentos dos peritos, acareações, reconhecimento, interrogatório e DEBATES. Alegações orais: 20 MINUTOS cada, prorrogáveis por 10; assistente: 10 minutos. Provas produzidas em uma só audiência. Nenhum ato será adiado, salvo prova faltante imprescindível, com condução coercitiva (§7º). Encerrados os debates, o juiz decide ou o faz em 10 DIAS (§9º)." },
  { id: "cpp-47", lei: "Código de Processo Penal", ref: "CPP art. 412",
    frente: "Prazo para concluir a primeira fase do júri (art. 412).",
    verso: "O procedimento será concluído no prazo máximo de 90 (NOVENTA) DIAS." },
  { id: "cpp-48", lei: "Código de Processo Penal", ref: "CPP art. 413 · caiu 2024 Q36",
    frente: "Pronúncia (art. 413): requisitos e conteúdo da fundamentação.",
    verso: "O juiz, fundamentadamente, PRONUNCIARÁ o acusado se convencido da MATERIALIDADE do fato e da existência de INDÍCIOS SUFICIENTES de autoria ou participação. A fundamentação limita-se à indicação da materialidade e dos indícios, devendo declarar o dispositivo legal em que julgar incurso o acusado e especificar as QUALIFICADORAS e causas de aumento (§1º). Se afiançável, arbitra a fiança (§2º). Decide, motivadamente, sobre a manutenção, revogação ou substituição da prisão ou medidas cautelares (§3º)." },
  { id: "cpp-49", lei: "Código de Processo Penal", ref: "CPP art. 414",
    frente: "Impronúncia (art. 414).",
    verso: "Não se convencendo da materialidade do fato ou de indícios suficientes de autoria ou participação, o juiz, fundamentadamente, IMPRONUNCIARÁ o acusado. Enquanto não extinta a punibilidade, poderá ser formulada NOVA denúncia ou queixa se houver PROVA NOVA." },
  { id: "cpp-50", lei: "Código de Processo Penal", ref: "CPP art. 415",
    frente: "Absolvição sumária no júri (art. 415).",
    verso: "O juiz, fundamentadamente, absolve desde logo o acusado quando: I provada a INEXISTÊNCIA DO FATO; II provado NÃO SER ELE AUTOR OU PARTÍCIPE; III o fato NÃO CONSTITUIR INFRAÇÃO PENAL; IV demonstrada causa de ISENÇÃO DE PENA ou de EXCLUSÃO DO CRIME. Parágrafo único: o inciso IV não se aplica à inimputabilidade do art. 26, caput, do CP, salvo quando for a única tese defensiva." },
  { id: "cpp-51", lei: "Código de Processo Penal", ref: "CPP art. 416 · caiu 2024 Q36",
    frente: "Qual o recurso cabível contra a impronúncia, a absolvição sumária e a pronúncia?",
    verso: "Impronúncia e absolvição sumária: APELAÇÃO (art. 416). Pronúncia: RECURSO EM SENTIDO ESTRITO (art. 581, IV). Pegadinha: 'da pronúncia cabe apelação'." },
  { id: "cpp-52", lei: "Código de Processo Penal", ref: "CPP arts. 417 e 418",
    frente: "Indícios contra outras pessoas e nova definição jurídica do fato (arts. 417 e 418).",
    verso: "Art. 417: se houver indícios de autoria ou participação de OUTRAS pessoas não incluídas na acusação, o juiz, ao pronunciar ou impronunciar, devolve os autos ao MP por 15 DIAS. Art. 418: o juiz poderá dar ao fato definição jurídica DIVERSA da constante da acusação, embora o acusado fique sujeito a PENA MAIS GRAVE." },
  { id: "cpp-53", lei: "Código de Processo Penal", ref: "CPP art. 419",
    frente: "Crime diverso e juiz incompetente (art. 419).",
    verso: "Quando o juiz se convencer, em discordância com a acusação, da existência de CRIME DIVERSO dos referidos no §1º do art. 74 e não for competente para o julgamento, REMETERÁ os autos ao juiz que o seja. Remetidos, o acusado preso fica à disposição deste." },
  { id: "cpp-54", lei: "Código de Processo Penal", ref: "CPP art. 420 · caiu 2024 Q36",
    frente: "Intimação da decisão de pronúncia (art. 420): quem é intimado pessoalmente e quem por publicação?",
    verso: "PESSOALMENTE: o acusado, o defensor NOMEADO e o Ministério Público. POR PUBLICAÇÃO (na forma do art. 370, §1º): o defensor CONSTITUÍDO, o querelante e o assistente do MP. Por EDITAL: o acusado SOLTO que não for encontrado (parágrafo único)." },
  { id: "cpp-55", lei: "Código de Processo Penal", ref: "CPP art. 421 · caiu 2024 Q36",
    frente: "Preclusa a pronúncia, surge circunstância que altera a classificação do crime: o que se faz (art. 421, §1º)?",
    verso: "Ainda que preclusa, havendo circunstância SUPERVENIENTE que altere a classificação do crime, o juiz ORDENA A REMESSA dos autos ao MINISTÉRIO PÚBLICO (para aditamento). O juiz NÃO altera de ofício. Em seguida, os autos são conclusos ao juiz para decisão (§2º)." },
  { id: "cpp-56", lei: "Código de Processo Penal", ref: "CPP arts. 422 a 424",
    frente: "Preparação do processo para julgamento em plenário (arts. 422 a 424).",
    verso: "Art. 422: o presidente do júri intima o MP (ou o querelante) e o defensor para, em 5 DIAS, apresentarem rol de testemunhas para o plenário, até 5, e juntarem documentos e requererem diligência. Art. 423: o juiz presidente ordena diligências para sanar nulidade ou esclarecer fato, e faz relatório sucinto, incluindo o processo em pauta. Art. 424: quando a lei local não atribuir ao presidente o preparo, o juiz competente remete-lhe os autos preparados até 5 DIAS ANTES do sorteio do art. 433." },
  { id: "cpp-57", lei: "Código de Processo Penal", ref: "CPP art. 425",
    frente: "Alistamento anual de jurados (art. 425): quantos?",
    verso: "Anualmente, pelo presidente do Tribunal do Júri: de 800 a 1.500 jurados nas comarcas com mais de 1.000.000 de habitantes; de 300 a 700 nas comarcas com mais de 100.000 habitantes; de 80 a 400 nas comarcas de menor população. Pode haver aumento do número e lista de suplentes. O juiz requisita indicações a autoridades locais, associações, instituições de ensino, universidades, sindicatos, repartições públicas e outros núcleos comunitários." },
  { id: "cpp-58", lei: "Código de Processo Penal", ref: "CPP art. 426",
    frente: "Lista geral de jurados (art. 426): publicação e alteração.",
    verso: "Publicada pela imprensa até 10 DE OUTUBRO de cada ano e divulgada em editais à porta do Tribunal do Júri. Pode ser alterada, de ofício ou por reclamação de qualquer do povo ao juiz presidente, até 10 DE NOVEMBRO (publicação definitiva). Os nomes e endereços, em cartões iguais, são verificados na presença do MP, de advogado indicado pela OAB e de defensor indicado pelas Defensorias, e guardados em urna fechada a chave. O jurado que integrou o Conselho de Sentença nos 12 meses antes da publicação fica excluído. A lista é completada anualmente, obrigatoriamente." },
  { id: "cpp-59", lei: "Código de Processo Penal", ref: "CPP art. 427",
    frente: "Desaforamento por ordem pública, dúvida sobre imparcialidade ou segurança do acusado (art. 427).",
    verso: "Se o interesse da ordem pública o reclamar ou houver dúvida sobre a imparcialidade do júri ou a segurança pessoal do acusado, o TRIBUNAL, a requerimento do MP, assistente, querelante ou acusado, ou por representação do juiz competente, poderá determinar o desaforamento para outra comarca da MESMA REGIÃO, preferindo-se as mais próximas. O pedido tem preferência de julgamento; o relator pode suspender o julgamento pelo júri; ouve-se o juiz presidente. Não se admite o pedido na pendência de recurso contra a pronúncia ou quando efetivado o julgamento, salvo fato ocorrido durante ou após o julgamento anulado." },
  { id: "cpp-60", lei: "Código de Processo Penal", ref: "CPP art. 428",
    frente: "Desaforamento por excesso de serviço (art. 428).",
    verso: "Se o julgamento não puder ser realizado no prazo de 6 (SEIS) MESES, contado do TRÂNSITO EM JULGADO da pronúncia, comprovado o excesso de serviço, ouvidos o juiz presidente e a parte contrária. Não se computa o tempo de adiamentos, diligências ou incidentes de interesse da defesa." },
  { id: "cpp-61", lei: "Código de Processo Penal", ref: "CPP arts. 429 a 431",
    frente: "Pauta do júri: ordem de preferência, assistente e intimações (arts. 429 a 431).",
    verso: "Preferência: I os acusados PRESOS; II dentre os presos, os que estiverem há MAIS TEMPO na prisão; III em igualdade de condições, os precedentemente PRONUNCIADOS. A lista dos processos é afixada na porta do edifício do Tribunal do Júri antes do primeiro julgamento da reunião. O ASSISTENTE só será admitido se requereu habilitação até 5 DIAS antes da sessão. O juiz presidente intima as partes, o ofendido (se possível), as testemunhas e os peritos (se requerido)." },
  { id: "cpp-62", lei: "Código de Processo Penal", ref: "CPP arts. 432 a 435",
    frente: "Sorteio e convocação dos jurados (arts. 432 a 435).",
    verso: "O juiz determina a intimação do MP, da OAB e da Defensoria para acompanharem o sorteio. O sorteio é a PORTAS ABERTAS, até completar 25 JURADOS, entre o 15º e o 10º dia ÚTIL antes da instalação da reunião; não é adiado pelo não comparecimento das partes. Os jurados são convocados pelo correio ou meio hábil, com transcrição dos arts. 436 a 446. Afixa-se à porta do Tribunal a relação dos jurados convocados, os nomes do acusado e dos procuradores e o dia, hora e local das sessões." },
  { id: "cpp-63", lei: "Código de Processo Penal", ref: "CPP art. 436",
    frente: "Serviço do júri (art. 436): obrigatoriedade, idade e recusa.",
    verso: "O serviço do júri é OBRIGATÓRIO. O alistamento compreende cidadãos MAIORES DE 18 ANOS de notória idoneidade. Ninguém pode ser excluído por cor, etnia, raça, credo, sexo, profissão, classe social ou econômica, origem ou grau de instrução. A recusa INJUSTIFICADA acarreta MULTA de 1 a 10 SALÁRIOS MÍNIMOS, conforme a condição econômica do jurado." },
  { id: "cpp-64", lei: "Código de Processo Penal", ref: "CPP art. 437",
    frente: "Quem está isento do serviço do júri (art. 437)?",
    verso: "I Presidente da República e Ministros de Estado; II Governadores e seus Secretários; III membros do Congresso Nacional, Assembleias e Câmaras Distrital e Municipais; IV Prefeitos; V Magistrados e membros do MP e da Defensoria Pública; VI servidores do Poder Judiciário, do MP e da Defensoria; VII autoridades e servidores da polícia e da segurança pública; VIII militares em serviço ativo; IX cidadãos maiores de 70 ANOS que REQUEIRAM a dispensa; X os que demonstrarem justo impedimento." },
  { id: "cpp-65", lei: "Código de Processo Penal", ref: "CPP arts. 438 a 441",
    frente: "Serviço alternativo, relevância do serviço e vantagens do jurado (arts. 438 a 441).",
    verso: "Art. 438: a recusa por convicção religiosa, filosófica ou política obriga a SERVIÇO ALTERNATIVO (atividades de caráter administrativo, assistencial, filantrópico ou produtivo no Judiciário, Defensoria, MP ou entidade conveniada), sob pena de SUSPENSÃO DOS DIREITOS POLÍTICOS enquanto não prestar. Art. 439: o exercício efetivo é SERVIÇO PÚBLICO RELEVANTE e gera PRESUNÇÃO de idoneidade moral. Art. 440: preferência, em igualdade de condições, em licitações públicas, concursos, promoção funcional e remoção voluntária. Art. 441: nenhum desconto nos vencimentos ou salário do jurado sorteado que comparecer." },
  { id: "cpp-66", lei: "Código de Processo Penal", ref: "CPP arts. 442 a 446",
    frente: "Faltas, escusas, dispensa e responsabilidade penal do jurado (arts. 442 a 446).",
    verso: "Art. 442: o jurado que, sem causa legítima, faltar ou retirar-se antes de dispensado recebe MULTA de 1 a 10 salários mínimos. Art. 443: só se aceita escusa fundada em motivo relevante COMPROVADO e apresentada até o momento da CHAMADA dos jurados (salvo força maior). Art. 444: o jurado só é dispensado por DECISÃO MOTIVADA do juiz presidente, consignada na ata. Art. 445: no exercício da função ou a pretexto de exercê-la, o jurado responde criminalmente nos mesmos termos dos JUÍZES TOGADOS. Art. 446: aos suplentes aplicam-se as regras de dispensas, faltas, escusas e responsabilidade penal." },
  { id: "cpp-67", lei: "Código de Processo Penal", ref: "CPP art. 447",
    frente: "Composição do Tribunal do Júri (art. 447).",
    verso: "1 juiz togado, que é o PRESIDENTE, e 25 JURADOS sorteados dentre os alistados, dos quais 7 (SETE) constituirão o CONSELHO DE SENTENÇA em cada sessão." },
  { id: "cpp-68", lei: "Código de Processo Penal", ref: "CPP arts. 448 e 449",
    frente: "Impedimentos entre jurados e quem não pode servir (arts. 448 e 449).",
    verso: "Impedidos de servir no mesmo Conselho: marido e mulher; ascendente e descendente; sogro e genro ou nora; irmãos e cunhados (durante o cunhadio); tio e sobrinho; padrasto, madrasta ou enteado (e quem mantém união estável reconhecida). Não pode servir o jurado que: I funcionou em julgamento anterior do mesmo processo; II no concurso de pessoas, integrou o Conselho que julgou outro acusado; III manifestou prévia disposição para condenar ou absolver." },
  { id: "cpp-69", lei: "Código de Processo Penal", ref: "CPP arts. 450 a 452",
    frente: "Impedidos entre si, jurados excluídos e mesmo Conselho em mais de um processo (arts. 450 a 452).",
    verso: "Art. 450: dos impedidos entre si, serve o que for sorteado em PRIMEIRO LUGAR. Art. 451: os jurados excluídos por impedimento, suspeição ou incompatibilidade são considerados para formar o número legal. Art. 452: o mesmo Conselho pode conhecer de MAIS DE UM processo no mesmo dia, se as partes aceitarem, devendo prestar novo compromisso." },
  { id: "cpp-70", lei: "Código de Processo Penal", ref: "CPP arts. 453 a 455",
    frente: "Sessões do júri e ausência do MP (arts. 453 a 455).",
    verso: "Art. 453: o Tribunal do Júri reúne-se nos períodos fixados pela lei local de organização judiciária. Art. 454: até a abertura dos trabalhos, o juiz presidente decide os casos de isenção, dispensa e adiamento, e manda consignar em ata. Art. 455: se o MP não comparecer, o juiz ADIA o julgamento para o primeiro dia desimpedido da mesma reunião; se a ausência não for justificada, comunica-se ao PROCURADOR-GERAL DE JUSTIÇA." },
  { id: "cpp-71", lei: "Código de Processo Penal", ref: "CPP art. 456",
    frente: "Falta do advogado do acusado ao júri (art. 456).",
    verso: "Sem escusa legítima e sem que outro seja constituído, comunica-se ao presidente da seccional da OAB, com a data da nova sessão. O julgamento é adiado SOMENTE UMA VEZ, e o acusado será julgado quando chamado novamente; o juiz intima a DEFENSORIA PÚBLICA para o novo julgamento, no primeiro dia desimpedido, observado o prazo mínimo de 10 DIAS." },
  { id: "cpp-72", lei: "Código de Processo Penal", ref: "CPP art. 457",
    frente: "Não comparecimento do acusado ao júri e adiamento (art. 457).",
    verso: "O julgamento NÃO será adiado pelo não comparecimento do acusado SOLTO, do assistente ou do advogado do querelante, regularmente intimados. Pedidos de adiamento e justificações são submetidos ao juiz presidente, salvo força maior. Se o acusado PRESO não for conduzido, o julgamento é adiado, salvo pedido de dispensa subscrito por ele e seu defensor." },
  { id: "cpp-73", lei: "Código de Processo Penal", ref: "CPP arts. 458 a 461",
    frente: "Testemunhas no júri (arts. 458 a 461).",
    verso: "Art. 458: a testemunha que, sem justa causa, não comparecer sofre a multa do art. 436, §2º, sem prejuízo da ação penal por desobediência. Art. 459: aplica-se às testemunhas o art. 441. Art. 460: antes de constituído o Conselho, ficam em local onde umas não ouçam as outras. Art. 461: o julgamento NÃO é adiado se a testemunha faltar, salvo se a parte requereu sua intimação por MANDADO, na oportunidade do art. 422, declarando não prescindir do depoimento e indicando sua localização; intimada e ausente, o juiz suspende e manda conduzi-la ou adia o julgamento. O julgamento será realizado se a testemunha não for encontrada, certificado por oficial de justiça." },
  { id: "cpp-74", lei: "Código de Processo Penal", ref: "CPP arts. 462 a 465",
    frente: "Instalação dos trabalhos do júri (arts. 462 a 465).",
    verso: "Art. 462: o juiz verifica se a urna contém as cédulas dos 25 jurados e o escrivão faz a chamada. Art. 463: comparecendo, pelo menos, 15 JURADOS, o presidente declara instalados os trabalhos e anuncia o processo; o oficial faz o pregão. Art. 464: sem esse número, sorteiam-se tantos suplentes quantos necessários e designa-se nova data. Art. 465: nomes dos suplentes consignados em ata, com expediente de convocação." },
  { id: "cpp-75", lei: "Código de Processo Penal", ref: "CPP arts. 466 a 469",
    frente: "Sorteio e recusa dos jurados (arts. 466 a 469).",
    verso: "Antes do sorteio, o presidente esclarece sobre impedimentos, suspeição e incompatibilidades (arts. 448 e 449) e adverte que os jurados sorteados NÃO podem comunicar-se entre si e com outrem nem manifestar opinião, sob pena de exclusão do Conselho e multa; a incomunicabilidade é certificada pelo oficial de justiça. Sorteiam-se 7 jurados. A defesa e depois o MP podem recusar, SEM MOTIVAR, até 3 JURADOS cada parte. Dois ou mais acusados: as recusas podem ser feitas por um só defensor; a separação dos julgamentos só ocorre se não houver 7 jurados." },
  { id: "cpp-76", lei: "Código de Processo Penal", ref: "CPP arts. 470 a 472",
    frente: "Arguição de impedimento, falta de número e compromisso dos jurados (arts. 470 a 472).",
    verso: "Art. 470: desacolhida a arguição de impedimento, suspeição ou incompatibilidade, o julgamento NÃO é suspenso, e constam da ata o fundamento e a decisão. Art. 471: sem número para formar o Conselho, adia-se o julgamento para o primeiro dia desimpedido, após sorteados os suplentes. Art. 472: formado o Conselho, o presidente exorta os jurados ('Em nome da lei, concito-vos a examinar esta causa com imparcialidade e a proferir a vossa decisão de acordo com a vossa consciência e os ditames da justiça') e eles respondem 'Assim o prometo'; recebem cópias da pronúncia e do relatório." },
  { id: "cpp-77", lei: "Código de Processo Penal", ref: "CPP arts. 473 e 474",
    frente: "Instrução em plenário e interrogatório (arts. 473 e 474).",
    verso: "Art. 473: o juiz presidente, o MP, o assistente, o querelante e o defensor tomam, sucessiva e diretamente, as declarações do ofendido e inquirem as testemunhas da acusação; para as da defesa, o defensor pergunta antes do MP e do assistente. Os jurados perguntam por intermédio do juiz presidente. Art. 474: no interrogatório, MP, assistente, querelante e defensor, nessa ordem, perguntam diretamente; jurados, por intermédio do juiz. NÃO se permite o uso de ALGEMAS no plenário, salvo absoluta necessidade para a ordem dos trabalhos, a segurança das testemunhas ou a integridade dos presentes." },
  { id: "cpp-78", lei: "Código de Processo Penal", ref: "CPP arts. 474-A e 475",
    frente: "Respeito à vítima em plenário e registro dos depoimentos (arts. 474-A e 475).",
    verso: "Art. 474-A: durante a instrução em plenário todos devem respeitar a dignidade da vítima, sob pena de responsabilização civil, penal e administrativa. Vedadas: manifestação sobre circunstâncias alheias aos fatos e linguagem ou material ofensivos. Art. 475: depoimentos e interrogatório registrados por gravação magnética, eletrônica, estenotipia ou técnica similar; a transcrição, após a degravação, consta dos autos." },
  { id: "cpp-79", lei: "Código de Processo Penal", ref: "CPP art. 476",
    frente: "Debates no plenário (art. 476): quem fala primeiro?",
    verso: "Encerrada a instrução, fala o MP, que sustenta a acusação nos limites da pronúncia (podendo sustentar circunstância agravante). Depois o assistente, depois a defesa. A acusação pode REPLICAR e a defesa TREPLICAR. Ação penal PRIVADA: primeiro o querelante, depois o MP (salvo se retomou a titularidade, art. 29)." },
  { id: "cpp-80", lei: "Código de Processo Penal", ref: "CPP art. 477",
    frente: "Tempo dos debates (art. 477).",
    verso: "Acusação e defesa: 1 HORA E MEIA cada; réplica: 1 HORA; tréplica: 1 HORA. Mais de um acusador ou defensor: combinam a divisão do tempo. Mais de 1 acusado: acrescenta-se 1 HORA ao tempo da acusação e da defesa e dobra-se o da réplica e da tréplica." },
  { id: "cpp-81", lei: "Código de Processo Penal", ref: "CPP art. 478",
    frente: "O que as partes NÃO podem referir nos debates, sob pena de nulidade (art. 478)?",
    verso: "I à decisão de PRONÚNCIA, às decisões posteriores que julgaram admissível a acusação ou ao uso de ALGEMAS, como argumento de autoridade; II ao SILÊNCIO do acusado ou à ausência de interrogatório por falta de requerimento, em seu prejuízo." },
  { id: "cpp-82", lei: "Código de Processo Penal", ref: "CPP arts. 479 a 481",
    frente: "Documentos e esclarecimentos aos jurados (arts. 479 a 481).",
    verso: "Art. 479: não é permitida a leitura de documento ou a exibição de objeto que não tenha sido juntado aos autos com antecedência mínima de 3 DIAS ÚTEIS, dando-se ciência à outra parte (inclui jornais, vídeos, gravações, fotografias, laudos, croquis sobre matéria de fato). Art. 480: as partes e os jurados podem pedir ao orador que indique a folha dos autos; concluídos os debates, o presidente pergunta se os jurados estão habilitados a julgar; eles têm acesso aos autos e instrumentos do crime se solicitarem. Art. 481: se a verificação de fato essencial não puder ser feita de imediato, o juiz DISSOLVE o Conselho e ordena diligências; se for perícia, nomeia perito e formula quesitos (partes têm 5 DIAS)." },
  { id: "cpp-83", lei: "Código de Processo Penal", ref: "CPP art. 482",
    frente: "Questionário do júri (art. 482): sobre o que o Conselho é questionado e como são redigidos os quesitos?",
    verso: "O Conselho de Sentença é questionado sobre MATÉRIA DE FATO e se o acusado deve ser ABSOLVIDO. Os quesitos são redigidos em proposições AFIRMATIVAS, SIMPLES e DISTINTAS, levando em conta os termos da pronúncia, o interrogatório e as alegações das partes." },
  { id: "cpp-84", lei: "Código de Processo Penal", ref: "CPP art. 483, caput",
    frente: "Ordem dos quesitos (art. 483).",
    verso: "I a MATERIALIDADE do fato; II a AUTORIA ou participação; III se o acusado deve ser ABSOLVIDO; IV se existe causa de DIMINUIÇÃO de pena alegada pela defesa; V se existe circunstância QUALIFICADORA ou causa de AUMENTO de pena reconhecidas na pronúncia." },
  { id: "cpp-85", lei: "Código de Processo Penal", ref: "CPP art. 483, §§1º a 6º",
    frente: "Votação dos quesitos: resposta negativa, quesito absolutório, desclassificação e tentativa (art. 483, §§1º a 6º).",
    verso: "§1º: resposta NEGATIVA de MAIS DE 3 jurados a qualquer dos quesitos I e II encerra a votação e implica absolvição. §2º: afirmados por mais de 3 os quesitos I e II, formula-se: 'O jurado absolve o acusado?'. §3º: decidindo pela condenação, quesitos sobre causa de diminuição e qualificadora/causa de aumento. §4º: DESCLASSIFICAÇÃO para infração de competência do juiz singular: quesito após o 2º ou 3º. §5º: TENTATIVA ou divergência de tipificação: quesito após o 2º. §6º: mais de um crime ou acusado: quesitos em SÉRIES distintas." },
  { id: "cpp-86", lei: "Código de Processo Penal", ref: "CPP arts. 484 a 488",
    frente: "Leitura dos quesitos, sala especial e votação (arts. 484 a 488).",
    verso: "Art. 484: o presidente lê os quesitos e pergunta às partes se têm requerimento ou reclamação; explica aos jurados o significado de cada quesito. Art. 485: não havendo dúvida, vão à SALA ESPECIAL o juiz presidente, os jurados, MP, assistente, querelante, defensor, escrivão e oficial de justiça; na falta de sala, o público se retira. Art. 486: cédulas de papel OPACO, 7 com a palavra SIM e 7 com NÃO. Art. 487: o oficial recolhe em URNAS SEPARADAS os votos e as cédulas não utilizadas (sigilo). Art. 488: o escrivão registra no termo a votação de cada quesito, o resultado e a conferência das cédulas não utilizadas." },
  { id: "cpp-87", lei: "Código de Processo Penal", ref: "CPP arts. 489 a 491",
    frente: "Decisão por maioria, contradição nas respostas e termo de votação (arts. 489 a 491).",
    verso: "Art. 489: as decisões do Tribunal do Júri são tomadas por MAIORIA de votos. Art. 490: em caso de CONTRADIÇÃO entre respostas, o presidente explica a contradição e submete novamente à votação os quesitos; se uma resposta prejudicar os seguintes, declara finda a votação. Art. 491: encerrada a votação, o termo é assinado pelo presidente, pelos jurados e pelas partes." },
  { id: "cpp-88", lei: "Código de Processo Penal", ref: "CPP art. 492",
    frente: "Sentença do juiz presidente no júri (art. 492): condenação e absolvição.",
    verso: "CONDENAÇÃO: fixa a pena-base; considera agravantes e atenuantes alegadas nos debates; impõe aumentos e diminuições das causas admitidas pelo júri; observa o art. 387; manda recolher o acusado ou o recomenda à prisão (se presentes os requisitos da preventiva) ou, em pena igual ou superior a 15 ANOS de reclusão, determina a EXECUÇÃO PROVISÓRIA; estabelece efeitos genéricos e específicos. ABSOLVIÇÃO: manda colocar em liberdade, revoga medidas restritivas e impõe, se for o caso, a medida de segurança cabível." },
  { id: "cpp-89", lei: "Código de Processo Penal", ref: "CPP art. 492, §§1º a 6º",
    frente: "Desclassificação, execução provisória e efeito suspensivo da apelação no júri (art. 492, §§1º a 6º).",
    verso: "§1º: desclassificada a infração para outra de competência do juiz singular, o presidente profere sentença (se for menor potencial ofensivo, arts. 69 e seguintes da Lei 9.099). §2º: o crime conexo não doloso contra a vida é julgado pelo juiz presidente. §3º: o presidente pode, excepcionalmente, deixar de autorizar a execução provisória. §4º: a apelação contra condenação igual ou superior a 15 anos NÃO tem efeito suspensivo. §5º: excepcionalmente o tribunal pode atribuí-lo, se o recurso não tem propósito meramente protelatório e levanta questão substancial que pode resultar em absolvição, anulação, novo julgamento ou redução da pena abaixo de 15 anos. §6º: o pedido pode ser feito na apelação ou em petição separada ao relator." },
  { id: "cpp-90", lei: "Código de Processo Penal", ref: "CPP arts. 493 a 496",
    frente: "Leitura da sentença e ata do júri (arts. 493 a 496).",
    verso: "Art. 493: a sentença é lida em plenário pelo presidente antes de encerrada a sessão. Art. 494: de cada sessão o escrivão lavra ATA assinada pelo presidente e pelas partes. Art. 495: a ata descreve fielmente as ocorrências (data e hora da instalação, juiz presidente e jurados presentes, faltosos e sanções, sorteio de suplentes, adiamento, formação do Conselho com os jurados sorteados e as recusas, compromisso e interrogatório, debates, incidentes, julgamento, publicidade). Art. 496: a falta da ata sujeita o responsável a sanções ADMINISTRATIVA e PENAL." },
  { id: "cpp-91", lei: "Código de Processo Penal", ref: "CPP art. 497",
    frente: "Atribuições do juiz presidente do Tribunal do Júri (art. 497).",
    verso: "I regular a POLÍCIA das sessões e prender os desobedientes; II requisitar força pública, sob sua exclusiva autoridade; III dirigir os debates; IV resolver questões incidentes que não dependam do júri; V nomear defensor ao acusado considerado INDEFESO, podendo dissolver o Conselho; VI mandar retirar da sala o acusado que dificultar o julgamento; VII suspender a sessão para diligências, mantida a incomunicabilidade; VIII interromper a sessão para sentença e repouso ou refeição dos jurados; IX decidir a arguição de EXTINÇÃO DE PUNIBILIDADE; X resolver questões de DIREITO; XI determinar diligências para sanar nulidade; XII regulamentar os APARTES (até 3 minutos cada, acrescidos ao tempo do orador)." },
  { id: "cpp-92", lei: "Código de Processo Penal", ref: "CPP art. 531",
    frente: "Audiência no procedimento SUMÁRIO (art. 531): prazo e ordem dos atos.",
    verso: "Será realizada no prazo máximo de 30 DIAS. Ordem: declarações do ofendido, testemunhas da acusação e da defesa, esclarecimentos de peritos, acareações, reconhecimento, INTERROGATÓRIO e, finalmente, o DEBATE." },
  { id: "cpp-93", lei: "Código de Processo Penal", ref: "CPP art. 532 · caiu 2024 Q35",
    frente: "Número de testemunhas no procedimento SUMÁRIO (art. 532).",
    verso: "Até 5 (CINCO) testemunhas arroladas pela acusação e 5 pela defesa (no ordinário são 8, art. 401)." },
  { id: "cpp-94", lei: "Código de Processo Penal", ref: "CPP arts. 533 a 536",
    frente: "Procedimento sumário: alegações finais, adiamento e testemunha presente (arts. 533 a 536).",
    verso: "Art. 533: aplicam-se os parágrafos do art. 400. Art. 534: alegações finais ORAIS, 20 minutos prorrogáveis por mais 10; assistente 10 minutos. Art. 535: nenhum ato é adiado, salvo prova faltante imprescindível, com condução coercitiva. Art. 536: a testemunha que comparecer é inquirida independentemente da suspensão da audiência." },
  { id: "cpp-95", lei: "Código de Processo Penal", ref: "CPP art. 538",
    frente: "Quando o JECrim encaminha as peças ao juízo comum (art. 538).",
    verso: "Nas infrações de menor potencial ofensivo, quando o juizado encaminhar ao juízo comum as peças para adoção de outro procedimento, observa-se o procedimento SUMÁRIO." },
  { id: "cpp-96", lei: "Código de Processo Penal", ref: "CPP art. 541",
    frente: "Restauração de autos extraviados ou destruídos (art. 541).",
    verso: "Os autos originais de processo penal extraviados ou destruídos, em primeira ou segunda instância, serão RESTAURADOS. Se existir e for exibida cópia autêntica ou certidão, valerá como original (§1º). Sem elas, o juiz manda: o ESCRIVÃO certificar o estado do processo segundo sua lembrança e reproduzir o que houver em protocolos e registros; requisitar cópias a IML, Instituto de Identificação, repartições, penitenciárias e cadeias; citar as partes pessoalmente ou por EDITAL com prazo de 10 DIAS (§2º). A restauração é feita na PRIMEIRA instância, ainda que os autos se tenham extraviado na segunda (§3º)." },
  { id: "cpp-97", lei: "Código de Processo Penal", ref: "CPP arts. 542 e 543",
    frente: "Restauração: audiência e diligências (arts. 542 e 543).",
    verso: "Art. 542: no dia designado, as partes são ouvidas, registrando-se em termo circunstanciado os pontos em que estiverem acordes e a conferência das certidões e reproduções. Art. 543: se não houve sentença, REINQUIREM-SE as testemunhas (substituíveis as falecidas ou em lugar incerto); os exames periciais são repetidos, de preferência pelos mesmos peritos; a prova documental é reproduzida por cópia autêntica ou por testemunhas; podem ser inquiridas autoridades, serventuários, peritos e outros que atuaram; MP e partes podem oferecer testemunhas e documentos." },
  { id: "cpp-98", lei: "Código de Processo Penal", ref: "CPP arts. 544 a 548",
    frente: "Restauração: prazos, custas e efeitos (arts. 544 a 548).",
    verso: "Art. 544: as diligências, salvo força maior, concluem-se em 20 DIAS; depois os autos vão conclusos; o juiz pode requisitar esclarecimentos em 5 dias. Art. 545: selos e taxas judiciárias já pagos NÃO são novamente cobrados. Art. 546: os causadores do extravio respondem pelas custas em DOBRO, sem prejuízo da responsabilidade criminal. Art. 547: julgada a restauração, os autos valem pelos originais; se aparecerem os originais, nestes continua o processo, com os da restauração apensos. Art. 548: até a decisão, a sentença condenatória em execução continua a produzir efeito, desde que conste da guia arquivada na cadeia ou penitenciária ou de registro inequívoco." },
  { id: "cpp-99", lei: "Código de Processo Penal", ref: "CPP art. 574",
    frente: "Recursos de OFÍCIO no processo penal (art. 574): quais são?",
    verso: "Os recursos são VOLUNTÁRIOS, exceto os interpostos de ofício pelo juiz: I da sentença que CONCEDER HABEAS CORPUS; II da que ABSOLVER desde logo o réu com fundamento em circunstância que exclua o crime ou isente de pena (art. 411)." },
  { id: "cpp-100", lei: "Código de Processo Penal", ref: "CPP arts. 575 a 577",
    frente: "Recursos: erro de funcionários, desistência do MP e legitimidade (arts. 575 a 577).",
    verso: "Art. 575: não são prejudicados os recursos que, por erro, falta ou omissão dos FUNCIONÁRIOS, não tiverem seguimento ou não forem apresentados no prazo. Art. 576: o MP NÃO pode DESISTIR de recurso que haja interposto. Art. 577: o recurso pode ser interposto pelo MP, pelo querelante, pelo réu, seu procurador ou seu defensor; não se admite recurso da parte sem INTERESSE na reforma ou modificação da decisão." },
  { id: "cpp-101", lei: "Código de Processo Penal", ref: "CPP art. 578",
    frente: "Como se interpõe o recurso e prazos de entrega (art. 578).",
    verso: "Por PETIÇÃO ou por TERMO nos autos, assinado pelo recorrente ou seu representante. Réu que não sabe ou não pode assinar: assina alguém a rogo, na presença de DUAS TESTEMUNHAS (§1º). A petição, com o despacho do juiz, é entregue ao escrivão até o dia seguinte ao último do prazo, que certifica a data da entrega (§2º). Recurso por termo: o escrivão, sob pena de SUSPENSÃO de 10 a 30 dias, faz conclusos os autos ao juiz até o dia seguinte ao último do prazo (§3º)." },
  { id: "cpp-102", lei: "Código de Processo Penal", ref: "CPP arts. 579 e 580",
    frente: "Fungibilidade dos recursos e extensão da decisão a corréus (arts. 579 e 580).",
    verso: "Art. 579: salvo MÁ-FÉ, a parte não é prejudicada pela interposição de um recurso por outro; o juiz que reconhece a impropriedade manda processá-lo pelo rito do recurso cabível. Art. 580: no concurso de agentes, a decisão do recurso interposto por um dos réus, se fundada em motivos que não sejam de caráter exclusivamente PESSOAL, aproveita aos outros." },
  { id: "cpp-103", lei: "Código de Processo Penal", ref: "CPP art. 581, I a XII",
    frente: "Recurso em sentido estrito (art. 581, I a XII): hipóteses de cabimento.",
    verso: "Cabe RESE da decisão que: I NÃO RECEBER a denúncia ou queixa; II concluir pela INCOMPETÊNCIA do juízo; III julgar procedentes as EXCEÇÕES, salvo a de suspeição; IV PRONUNCIAR o réu; V conceder, negar, arbitrar, cassar ou julgar inidônea a FIANÇA, indeferir requerimento de PRISÃO PREVENTIVA ou revogá-la, conceder LIBERDADE PROVISÓRIA ou relaxar a prisão em flagrante; VII julgar quebrada a fiança ou perdido o seu valor; VIII decretar a PRESCRIÇÃO ou julgar extinta a punibilidade; IX indeferir o reconhecimento da prescrição ou de outra causa extintiva; X conceder ou negar HABEAS CORPUS; XI conceder, negar ou revogar a SUSPENSÃO CONDICIONAL da pena; XII conceder, negar ou revogar LIVRAMENTO CONDICIONAL." },
  { id: "cpp-104", lei: "Código de Processo Penal", ref: "CPP art. 581, XIII a XXV",
    frente: "Recurso em sentido estrito (art. 581, XIII a XXV): demais hipóteses.",
    verso: "XIII anular o processo da instrução criminal, no todo ou em parte; XIV incluir jurado na lista geral ou dela o excluir; XV denegar a apelação ou a julgar deserta; XVI ordenar a suspensão do processo por questão prejudicial; XVII decidir sobre a unificação de penas; XVIII decidir o incidente de falsidade; XIX decretar medida de segurança depois do trânsito em julgado; XX impor medida de segurança por transgressão de outra; XXI manter ou substituir a medida de segurança (art. 774); XXII revogar a medida de segurança; XXIII deixar de revogar a medida de segurança; XXIV converter a multa em detenção ou prisão simples; XXV RECUSAR HOMOLOGAÇÃO à proposta de ACORDO DE NÃO PERSECUÇÃO PENAL (art. 28-A). O inciso VI está revogado." },
  { id: "cpp-105", lei: "Código de Processo Penal", ref: "CPP arts. 582 e 583",
    frente: "Para onde vai o RESE e quando sobe nos próprios autos (arts. 582 e 583).",
    verso: "Art. 582: sempre para o Tribunal de Apelação, SALVO nos casos dos incisos V, X e XIV (o XIV vai ao presidente do Tribunal). Art. 583: sobem nos próprios autos os recursos interpostos de ofício; nos casos do art. 581, I, III, IV, VI, VIII e X; e quando o recurso não prejudicar o andamento do processo. O recurso da pronúncia sobe em TRASLADO quando, havendo dois ou mais réus, qualquer deles se conformar ou todos não tiverem sido intimados." },
  { id: "cpp-106", lei: "Código de Processo Penal", ref: "CPP art. 584",
    frente: "Efeito suspensivo do RESE (art. 584).",
    verso: "Têm efeito suspensivo os recursos nos casos de perda da fiança, de concessão de livramento condicional e dos incisos XV, XVII e XXIV do art. 581. O recurso da PRONÚNCIA suspende tão-somente o JULGAMENTO (§2º). O recurso do despacho que julgar quebrada a fiança suspende unicamente o efeito da perda da METADE do seu valor (§3º). Ao recurso de impronúncia ou do inciso VIII aplicam-se os arts. 596 e 598 (§1º)." },
  { id: "cpp-107", lei: "Código de Processo Penal", ref: "CPP art. 585", conferir: true,
    frente: "Réu e recurso da pronúncia (art. 585).",
    verso: "O réu não poderá recorrer da pronúncia senão depois de preso, salvo se prestar fiança nos casos em que a lei a admitir. Observação: a prisão em razão da pronúncia não é automática, devendo atender ao art. 413, §3º e aos requisitos da preventiva." },
  { id: "cpp-108", lei: "Código de Processo Penal", ref: "CPP art. 586",
    frente: "Prazo do recurso voluntário e do recurso contra a lista de jurados (art. 586).",
    verso: "O recurso voluntário poderá ser interposto no prazo de 5 (CINCO) DIAS. No caso do art. 581, XIV (lista de jurados), o prazo é de 20 DIAS, contado da publicação definitiva da lista." },
  { id: "cpp-109", lei: "Código de Processo Penal", ref: "CPP arts. 587 a 590",
    frente: "RESE por instrumento: traslado, razões e juízo de retratação (arts. 587 a 590).",
    verso: "Art. 587: quando sobe por instrumento, a parte indica as peças para traslado, que é extraído, conferido e concertado em 5 DIAS. Art. 588: razões em 2 DIAS contados da interposição (ou da vista após o traslado), e vista ao recorrido por igual prazo; se o recorrido é o réu, é intimado na pessoa do defensor. Art. 589: com a resposta ou sem ela, o juiz, em 2 DIAS, REFORMA ou SUSTENTA o despacho (juízo de retratação); se reformar, a parte contrária pode recorrer por simples petição. Art. 590: se o escrivão não conseguir extrair o traslado no prazo, o juiz pode prorrogá-lo até o DOBRO." },
  { id: "cpp-110", lei: "Código de Processo Penal", ref: "CPP arts. 591 e 592",
    frente: "Apresentação do recurso ao tribunal e devolução dos autos (arts. 591 e 592).",
    verso: "Art. 591: os recursos são apresentados ao juiz ou tribunal ad quem em 5 DIAS da publicação da resposta do juiz a quo, ou entregues ao Correio no mesmo prazo. Art. 592: publicada a decisão do ad quem, os autos são devolvidos ao juiz a quo em 5 DIAS." },
  { id: "cpp-111", lei: "Código de Processo Penal", ref: "CPP art. 593, I a III",
    frente: "Apelação no processo penal (art. 593): prazo e hipóteses de cabimento.",
    verso: "Cabe apelação no prazo de 5 (CINCO) DIAS: I das sentenças definitivas de condenação ou absolvição do juiz SINGULAR; II das decisões definitivas, ou com força de definitivas, do juiz singular não previstas no RESE; III das decisões do TRIBUNAL DO JÚRI quando: a) nulidade POSTERIOR à pronúncia; b) sentença do juiz presidente CONTRÁRIA À LEI EXPRESSA ou à decisão dos jurados; c) ERRO ou INJUSTIÇA na aplicação da pena ou da medida de segurança; d) decisão dos jurados MANIFESTAMENTE CONTRÁRIA À PROVA dos autos." },
  { id: "cpp-112", lei: "Código de Processo Penal", ref: "CPP art. 593, §§1º a 4º",
    frente: "Apelação contra decisões do júri: retificação, nova decisão e vedação do RESE (art. 593, §§1º a 4º).",
    verso: "§1º: sentença contrária à lei expressa ou divergente das respostas dos jurados: o tribunal RETIFICA. §2º: apelação por erro ou injustiça na pena: o tribunal, dando provimento, retifica a aplicação da pena ou da medida de segurança. §3º: decisão manifestamente contrária à prova: provimento sujeita o réu a NOVO JULGAMENTO, e NÃO se admite segunda apelação pelo mesmo motivo. §4º: quando cabível a apelação, NÃO se usa o RESE, ainda que somente de parte da decisão se recorra." },
  { id: "cpp-113", lei: "Código de Processo Penal", ref: "CPP arts. 596 e 597",
    frente: "Efeitos da apelação (arts. 596 e 597).",
    verso: "Art. 596: a apelação da sentença ABSOLUTÓRIA não impede que o réu seja posto imediatamente em liberdade; não suspende a execução da medida de segurança aplicada provisoriamente. Art. 597: a apelação de sentença CONDENATÓRIA tem EFEITO SUSPENSIVO, salvo o art. 393, a aplicação provisória de interdições de direitos e de medidas de segurança (arts. 374 e 378) e a suspensão condicional da pena." },
  { id: "cpp-114", lei: "Código de Processo Penal", ref: "CPP art. 598",
    frente: "Apelação supletiva do ofendido (art. 598).",
    verso: "Nos crimes de competência do júri ou do juiz singular, se o MP não apelar no prazo legal, o OFENDIDO ou qualquer das pessoas do art. 31, ainda que não habilitado como assistente, poderá apelar, SEM efeito suspensivo. Prazo: 15 DIAS, correndo do dia em que terminar o prazo do MP." },
  { id: "cpp-115", lei: "Código de Processo Penal", ref: "CPP arts. 599 a 603",
    frente: "Apelação: extensão, razões e subida dos autos (arts. 599 a 603).",
    verso: "Art. 599: pode ser interposta quanto a todo o julgado ou a parte dele. Art. 600: assinado o termo, apelante e depois apelado têm 8 DIAS cada um para razões (3 dias nas CONTRAVENÇÕES); assistente arrazoa em 3 dias, após o MP; prazos comuns se forem dois ou mais apelantes ou apelados; o apelante pode declarar que quer arrazoar na instância superior. Art. 601: findos os prazos, os autos sobem em 5 DIAS (30 dias na hipótese do art. 603, segunda parte); com mais de um réu, o apelante promove a extração do traslado (30 dias). Art. 602: os autos são apresentados ao tribunal ou entregues ao Correio sob registro. Art. 603: a apelação sobe nos autos originais; fora do DF e das comarcas sede de Tribunal, fica em cartório traslado dos termos essenciais." },
  { id: "cpp-116", lei: "Código de Processo Penal", ref: "CPP arts. 609 e 610",
    frente: "Julgamento dos recursos nos tribunais: embargos infringentes e vista ao Procurador-Geral (arts. 609 e 610).",
    verso: "Art. 609: recursos, apelações e embargos são julgados pelos TJs, câmaras ou turmas criminais. Decisão NÃO UNÂNIME desfavorável ao réu: EMBARGOS INFRINGENTES e de nulidade, em 10 DIAS da publicação do acórdão (restritos à matéria divergente). Art. 610: no RESE (exceto habeas corpus) e nas apelações de contravenção ou crime de DETENÇÃO, os autos vão com vista ao procurador-geral por 5 DIAS e, depois, ao relator por igual prazo; no julgamento, 10 MINUTOS para os advogados e para o procurador-geral." },
  { id: "cpp-117", lei: "Código de Processo Penal", ref: "CPP arts. 612 a 614",
    frente: "Habeas corpus nos tribunais e apelação de crime apenado com reclusão (arts. 612 a 614).",
    verso: "Art. 612: habeas corpus: designado o relator, julgam-se na PRIMEIRA SESSÃO. Art. 613: apelações de crime apenado com RECLUSÃO seguem o art. 610 com modificações: relatório e REVISOR; prazos em DOBRO; tempo dos debates de UM QUARTO DE HORA. Art. 614: se não for possível observar os prazos dos arts. 610 e 613, os motivos da demora são declarados nos autos." },
  { id: "cpp-118", lei: "Código de Processo Penal", ref: "CPP arts. 615 a 618",
    frente: "Decisão colegiada, empate e agravamento da pena (arts. 615 a 618).",
    verso: "Art. 615: o tribunal decide por MAIORIA; havendo EMPATE, prevalece a decisão mais FAVORÁVEL ao imputado, proclamando-se imediatamente o resultado, ainda que tomado sem a totalidade dos integrantes. O acórdão é apresentado na primeira sessão seguinte ou no prazo de 2 sessões. Art. 616: no julgamento das apelações o tribunal pode proceder a novo interrogatório, reinquirir testemunhas ou determinar diligências. Art. 617: não se pode AGRAVAR a pena quando somente o réu apelou (vedação da reformatio in pejus). Art. 618: regimentos dos tribunais estabelecem normas complementares." },
  { id: "cpp-119", lei: "Código de Processo Penal", ref: "CPP arts. 619 e 620",
    frente: "Embargos de declaração no CPP (arts. 619 e 620): prazo e cabimento.",
    verso: "Cabem contra acórdãos dos Tribunais, câmaras ou turmas, no prazo de 2 (DOIS) DIAS contados da publicação, quando houver AMBIGUIDADE, OBSCURIDADE, CONTRADIÇÃO ou OMISSÃO. O requerimento indica os pontos; é apresentado pelo relator e julgado, independentemente de revisão, na primeira sessão; se não preenchidas as condições, o relator indefere desde logo." },
  { id: "cpp-120", lei: "Código de Processo Penal", ref: "CPP arts. 621 a 623",
    frente: "Revisão criminal: hipóteses, prazo e legitimidade (arts. 621 a 623).",
    verso: "Art. 621: admitida quando: I a sentença condenatória for contrária ao texto expresso da lei penal ou à evidência dos autos; II se fundar em depoimentos, exames ou documentos comprovadamente falsos; III após a sentença, se descobrirem novas provas de inocência ou de circunstância que autorize diminuição especial da pena. Art. 622: pode ser requerida em QUALQUER TEMPO, antes da extinção da pena ou após; não se admite reiteração do pedido, salvo com novas provas. Art. 623: pelo próprio réu, por procurador habilitado ou, em caso de morte, por cônjuge, ascendente, descendente ou irmão." },
  { id: "cpp-121", lei: "Código de Processo Penal", ref: "CPP arts. 624 e 625",
    frente: "Revisão criminal: competência e processamento (arts. 624 e 625).",
    verso: "Art. 624: julga o STF as condenações que proferiu; nos demais casos, os Tribunais de Justiça (ou de Alçada). Nos TJs, câmaras ou turmas criminais REUNIDAS em sessão conjunta. Art. 625: o requerimento é distribuído a um relator e a um revisor; o relator deve ser desembargador que NÃO tenha decidido em qualquer fase do processo; é instruído com a certidão do trânsito em julgado; o procurador-geral dá parecer em 10 DIAS; relator e revisor examinam em igual prazo." },
  { id: "cpp-122", lei: "Código de Processo Penal", ref: "CPP arts. 626 a 631",
    frente: "Revisão criminal: julgamento, indenização e morte do condenado (arts. 626 a 631).",
    verso: "Art. 626: julgada procedente, o tribunal pode ALTERAR a classificação da infração, ABSOLVER o réu, MODIFICAR a pena ou ANULAR o processo; NÃO pode AGRAVAR a pena. Art. 627: a absolvição restabelece todos os direitos perdidos, impondo-se, se for caso, medida de segurança. Art. 630: o tribunal pode reconhecer o direito a JUSTA INDENIZAÇÃO, liquidada no juízo cível (responde a União ou o Estado conforme a justiça); NÃO é devida se o erro proceder de ato ou falta do próprio impetrante (confissão ou ocultação de prova) ou se a acusação foi meramente PRIVADA. Art. 631: falecendo o condenado no curso da revisão, o presidente nomeia CURADOR para a defesa." },
  { id: "cpp-123", lei: "Código de Processo Penal", ref: "CPP arts. 637 e 638",
    frente: "Recurso extraordinário e especial no processo penal (arts. 637 e 638).",
    verso: "Art. 637: o recurso extraordinário NÃO tem efeito suspensivo; arrazoado pelo recorrido, os originais baixam à primeira instância para execução da sentença. Art. 638: RE e recurso especial são processados e julgados no STF e no STJ na forma de leis especiais, da lei processual civil e dos regimentos internos." },
  { id: "cpp-124", lei: "Código de Processo Penal", ref: "CPP arts. 639 a 646",
    frente: "Carta testemunhável (arts. 639 a 646).",
    verso: "Cabe: I da decisão que DENEGAR o recurso; II da que, admitindo o recurso, OBSTAR à sua expedição e seguimento. É requerida ao escrivão ou ao secretário do tribunal nas 48 HORAS seguintes ao despacho que denegar o recurso. O escrivão dá recibo e entrega a carta em 5 DIAS (RESE) ou 60 DIAS (recurso extraordinário). Quem se negar a dar recibo ou deixar de entregar o instrumento será suspenso por 30 DIAS. A carta NÃO tem efeito suspensivo." },
  { id: "cpp-125", lei: "Código de Processo Penal", ref: "CPP art. 647",
    frente: "Habeas corpus no CPP (art. 647): quando se dá?",
    verso: "Sempre que alguém sofrer ou se achar na IMINÊNCIA de sofrer violência ou coação ILEGAL na sua liberdade de ir e vir, SALVO nos casos de punição DISCIPLINAR. Pode ser preventivo (salvo-conduto) ou repressivo (liberatório)." },
  { id: "cpp-126", lei: "Código de Processo Penal", ref: "CPP art. 647-A",
    frente: "Habeas corpus de ofício (art. 647-A).",
    verso: "No âmbito de sua competência, qualquer autoridade judicial pode expedir de OFÍCIO ordem de habeas corpus, individual ou coletivo, quando, no curso de qualquer processo, verificar violação ao ordenamento que cause coação à liberdade de locomoção. Pode ser concedida de ofício, em processo de competência originária ou recursal, ainda que não conhecidos a ação ou o recurso." },
  { id: "cpp-127", lei: "Código de Processo Penal", ref: "CPP art. 648",
    frente: "Quando a coação é considerada ilegal (art. 648)?",
    verso: "I quando NÃO houver JUSTA CAUSA; II alguém preso por MAIS TEMPO do que determina a lei; III quem ordenar a coação NÃO tiver COMPETÊNCIA; IV tiver CESSADO o motivo que autorizou a coação; V não for alguém admitido a prestar FIANÇA, nos casos em que a lei a autoriza; VI o processo for MANIFESTAMENTE NULO; VII extinta a PUNIBILIDADE." },
  { id: "cpp-128", lei: "Código de Processo Penal", ref: "CPP arts. 649 a 653",
    frente: "Habeas corpus: efeito, competência, nulidade e custas (arts. 649 a 653).",
    verso: "Art. 649: o juiz ou tribunal faz passar imediatamente a ordem, seja qual for a autoridade coatora. Art. 650: competência originária: STF (art. 101, I, g, CF) e TRIBUNAIS DE APELAÇÃO quando atos de coação forem atribuídos a governadores ou interventores, ao prefeito do DF ou a secretários ou chefes de Polícia; a competência do juiz cessa quando a coação provier de autoridade judiciária de igual ou superior jurisdição; não cabe HC contra prisão administrativa dos responsáveis por dinheiro da Fazenda Pública, salvo prova de quitação ou depósito ou prisão além do prazo. Art. 651: a concessão não obsta nem põe termo ao processo, se não conflitar com os fundamentos. Art. 652: concedido por NULIDADE do processo, este será RENOVADO. Art. 653: ordenada a soltura, será condenada nas custas a autoridade que, por má-fé ou evidente abuso de poder, tiver determinado a coação." },
  { id: "cpp-129", lei: "Código de Processo Penal", ref: "CPP art. 654",
    frente: "Quem pode impetrar habeas corpus e requisitos da petição (art. 654).",
    verso: "Qualquer PESSOA, em seu favor ou de outrem, bem como o MINISTÉRIO PÚBLICO. A petição contém: nome de quem sofre ou está ameaçado e de quem exerce a coação; declaração da espécie de constrangimento (ou razões do temor); assinatura do impetrante ou de alguém a seu rogo e a designação das residências. Juízes e tribunais podem expedir ordem de habeas corpus de ofício." },
  { id: "cpp-130", lei: "Código de Processo Penal", ref: "CPP arts. 655 a 659",
    frente: "Habeas corpus: embaraço, apresentação do paciente e perda do objeto (arts. 655 a 659).",
    verso: "Art. 655: quem embaraçar ou procrastinar a expedição de ordem de habeas corpus, informações, condução e apresentação do paciente ou soltura é MULTADO, sem prejuízo de outras penas. Art. 656: recebida a petição, o juiz, se necessário, e estando preso o paciente, manda que lhe seja apresentado; desobediência: mandado de prisão contra o detentor. Art. 657: nenhum motivo escusa a apresentação do paciente preso, salvo grave enfermidade, não estar sob a guarda de quem se atribui a detenção ou comparecimento não determinado por juiz ou tribunal. Art. 658: o detentor declara à ordem de quem o paciente está preso. Art. 659: se já cessou a violência ou coação ilegal, o pedido é julgado PREJUDICADO." },
  { id: "cpp-131", lei: "Código de Processo Penal", ref: "CPP art. 660",
    frente: "Julgamento do habeas corpus pelo juiz (art. 660): prazo e salvo-conduto.",
    verso: "Efetuadas as diligências e interrogado o paciente, o juiz decide, fundamentadamente, em 24 (VINTE E QUATRO) HORAS. Decisão favorável: o paciente é logo posto em liberdade, salvo se por outro motivo dever ser mantido preso. Ilegalidade evidenciada pelos documentos: cessa imediatamente o constrangimento. Se a ilegalidade for não admissão à fiança, o juiz arbitra o valor. Ordem concedida para evitar ameaça: SALVO-CONDUTO assinado pelo juiz (habeas corpus preventivo). Cópia da decisão é enviada à autoridade coatora." },
  { id: "cpp-132", lei: "Código de Processo Penal", ref: "CPP arts. 661 a 667",
    frente: "Habeas corpus nos tribunais (arts. 661 a 667).",
    verso: "Art. 661: em competência originária do Tribunal, a petição é apresentada ao secretário, que a envia ao presidente do tribunal, da câmara ou da turma. Art. 662: o presidente, se necessário, requisita informações por escrito; faltando requisitos do art. 654, §1º, manda preencher. Art. 663: se o HC deve ser indeferido in limine, a petição vai ao tribunal, câmara ou turma. Art. 664: recebidas as informações, o HC é julgado na PRIMEIRA SESSÃO (podendo adiar para a seguinte); decisão por maioria; em EMPATE, voto de desempate do presidente se não votou, senão prevalece a decisão mais FAVORÁVEL ao paciente. Art. 665: o secretário lavra a ordem, assinada pelo presidente. Arts. 666 e 667: regimentos estabelecem normas complementares; no HC originário do STF e nos recursos das decisões de última ou única instância denegatórias, observa-se o disposto, com regras do regimento interno." }
]);
